preConditionHook:
// EEC E16 "Introducing Serial Correlation" -- the book's EXACT composite,
// deliberately NOT split: the last-trade cooldown gate AND the countertrend
// extreme-close entry. The gate reads the measured accessors (the
// `positionprofit(n)`/`totaltrades` register row): PositionProfit(1) is the
// most recently closed position net of the round turn, BarsSinceExit is 0 on
// the exit's fill bar, TotalTrades is incremented at that close.
scGateOk =
    (el_gt(ctx.PositionProfit(1), 0.0) &&
     el_ge((double)ctx.BarsSinceExit(), waitAfterWin)) ||
    (el_le(ctx.PositionProfit(1), 0.0) &&
     el_ge((double)ctx.BarsSinceExit(), waitAfterLoss)) ||
    ctx.TotalTrades() == 0;
// close = Lowest(close, xbars) / Highest(close, xbars): Extremes semantics
// (seed index 0, strict el_lt/el_gt scan) and the `=` trap -- the equality
// against the window extreme becomes el_le/el_ge (Breakout is the reference).
scLowestC = close[0];
scHighestC = close[0];
for (int i = 1; i < (int)xbars; ++i) {
    if (el_lt(close[i], scLowestC)) { scLowestC = close[i]; }
    if (el_gt(close[i], scHighestC)) { scHighestC = close[i]; }
}
